"""Persist XML slides generated by the XML tool registry."""

from __future__ import annotations

import os
import shutil
import time
import xml.etree.ElementTree as ET

from backend.workflows.slidegen_workflow.graph.stage import State
from langchain_core.runnables import RunnableConfig


async def render_xml(state: State, config: RunnableConfig) -> State:
    """Validate and save the generated XML artifact."""
    start_time = time.time()
    idx = state["current_slide_index"]
    retry_count = state.get("retry_count", 0)
    configurable = config.get("configurable", {}) if config else {}
    temp_dir = configurable.get("temp_dir")
    temp_debug_dir = configurable.get("temp_debug_dir")

    if not temp_dir:
        raise ValueError("Missing required resource (temp_dir) in XML renderer config.")

    xml_content = state.get("current_xml_content", "")
    if not xml_content:
        raise ValueError("XML tool returned empty content.")

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as exc:
        raise ValueError(f"XML tool returned invalid XML: {exc}") from exc
    if root.tag != "presentation":
        raise ValueError("XML root element must be <presentation>.")

    xml_dir = os.path.join(temp_dir, "xml")
    os.makedirs(xml_dir, exist_ok=True)
    xml_path = os.path.join(xml_dir, f"slide_{idx + 1}.xml")
    with open(xml_path, "w", encoding="utf-8") as file:
        file.write(xml_content)

    state["current_xml_path"] = xml_path
    # XML is the workflow artifact. PNG capture is intentionally disabled:
    # the web preview remains available on demand, while generation no longer
    # spends time opening Chromium and writing image files.
    state["current_image_path"] = ""

    if temp_debug_dir:
        debug_xml_dir = os.path.join(temp_debug_dir, "xml")
        os.makedirs(debug_xml_dir, exist_ok=True)
        debug_path = os.path.join(debug_xml_dir, f"slide_{idx + 1}_{retry_count}.xml")
        shutil.copy2(xml_path, debug_path)

        debug_info = state.get("all_debug_info", [])
        debug_info.append({
            "index": idx,
            "tool_call": state.get("current_tool_call", {}),
            "xml_path": debug_path,
            "png_path": "",
            "feedback": state.get("vlm_feedback", ""),
            "retry_count": retry_count,
        })
        state["all_debug_info"] = debug_info

    print(f"Saved XML slide {idx + 1} at: {xml_path}")
    print(f"PNG capture skipped for XML slide {idx + 1}.")
    print(f"XML persistence took {time.time() - start_time:.2f}s.")
    return state
